alter policy "source broker reads private buyer" on public.genz_buyers using ((select public.genz_is_member()) and (select auth.uid()) = source_user_id);
alter policy "source broker updates private buyer" on public.genz_buyers using ((select public.genz_is_member()) and (select auth.uid()) = source_user_id) with check ((select public.genz_is_member()) and (select auth.uid()) = source_user_id);
alter policy "brokers update own profile" on public.genz_profiles using ((select public.genz_is_member()) and (select auth.uid()) = id) with check ((select public.genz_is_member()) and (select auth.uid()) = id);
alter policy "source broker updates requirement" on public.genz_requirements using ((select public.genz_is_member()) and (select auth.uid()) = source_user_id) with check ((select public.genz_is_member()) and (select auth.uid()) = source_user_id);
alter policy "source broker deletes requirement" on public.genz_requirements using ((select public.genz_is_member()) and (select auth.uid()) = source_user_id);
alter policy "listing broker creates property" on public.genz_properties with check ((select public.genz_is_member()) and (select auth.uid()) = listing_user_id);
alter policy "listing broker updates property" on public.genz_properties using ((select public.genz_is_member()) and (select auth.uid()) = listing_user_id) with check ((select public.genz_is_member()) and (select auth.uid()) = listing_user_id);
alter policy "listing broker deletes property" on public.genz_properties using ((select public.genz_is_member()) and (select auth.uid()) = listing_user_id);
alter policy "listing broker reads private owner" on public.genz_property_private using ((select public.genz_is_member()) and (select auth.uid()) = listing_user_id);
alter policy "listing broker creates private owner" on public.genz_property_private with check ((select public.genz_is_member()) and (select auth.uid()) = listing_user_id);
alter policy "listing broker updates private owner" on public.genz_property_private using ((select public.genz_is_member()) and (select auth.uid()) = listing_user_id) with check ((select public.genz_is_member()) and (select auth.uid()) = listing_user_id);
alter policy "listing broker deletes private owner" on public.genz_property_private using ((select public.genz_is_member()) and (select auth.uid()) = listing_user_id);
alter policy "deal participants read room" on public.genz_deals using ((select public.genz_is_member()) and ((select auth.uid()) = buyer_user_id or (select auth.uid()) = listing_user_id));
alter policy "deal participants update room" on public.genz_deals using ((select public.genz_is_member()) and ((select auth.uid()) = buyer_user_id or (select auth.uid()) = listing_user_id)) with check ((select public.genz_is_member()) and ((select auth.uid()) = buyer_user_id or (select auth.uid()) = listing_user_id));
alter policy "deal participants read events" on public.genz_deal_events using ((select public.genz_is_member()) and exists (select 1 from public.genz_deals d where d.id = genz_deal_events.deal_id and ((select auth.uid()) = d.buyer_user_id or (select auth.uid()) = d.listing_user_id)));
alter policy "deal participants add events" on public.genz_deal_events with check ((select public.genz_is_member()) and actor_user_id = (select auth.uid()) and exists (select 1 from public.genz_deals d where d.id = genz_deal_events.deal_id and ((select auth.uid()) = d.buyer_user_id or (select auth.uid()) = d.listing_user_id)));
alter policy "invite visibility" on public.genz_invites using ((select public.genz_is_admin()) or invited_by_user_id = (select auth.uid()) or redeemed_by_user_id = (select auth.uid()));
